// TB6600 + NEMA23 (common-cathode подключение)
//   TB6600 PUL+  -> Nano D2  (STEP)
//   TB6600 DIR+  -> Nano D3  (DIR)
//   TB6600 ENA+  -> Nano D4  (ENA, LOW = драйвер включён)
//   PUL- / DIR- / ENA-  -> GND (Nano)
//   Питание TB6600: отдельный БП 12–36В (НЕ от Nano!)
//   Мотор: A+ A- B+ B- -> клеммы TB6600

#include <AccelStepper.h>

#define STEP_PIN 2
#define DIR_PIN  3
#define ENA_PIN  4

#define STEPS_PER_REV 200    // NEMA23 1.8° = 200 шагов/оборот
#define MICROSTEPS    8      // ставь по DIP-переключателям SW1–SW3 драйвера
#define STEPS_TOTAL   (STEPS_PER_REV * MICROSTEPS)   // шагов на оборот

AccelStepper stepper(AccelStepper::DRIVER, STEP_PIN, DIR_PIN);

void setup() {
  pinMode(ENA_PIN, OUTPUT);
  digitalWrite(ENA_PIN, LOW);   // LOW = драйвер включён

  stepper.setMaxSpeed(400);       // шагов/сек
  stepper.setAcceleration(800);   // разгон, шагов/сек²

  // Пример: 5 оборотов вперёд (200*8*5 = 8000 шагов)
  stepper.moveTo(5L * STEPS_TOTAL);
}

void loop() {
  if (stepper.distanceToGo() != 0) stepper.run();
}
